        private async Task UserStatus(string cnic, bool status)
        {
            // Update all records with the same CNIC in memory
            var recordsToUpdate = filteredFileContent.Where(x => x.Cnic == cnic).ToList();

            // Update the status in memory first
            foreach (var record in recordsToUpdate)
            {
                record.Status = status;
            }

            // Now update the database records for those with the same CNIC
            var recordsInDb = await context.Files.Where(x => x.Cnic == cnic).ToListAsync();
            foreach (var record in recordsInDb)
            {
                record.Status = status;
            }

            // Save changes to the database
            await context.SaveChangesAsync();
        }

